program:
(()=>{

const $ = id => document.getElementById(id);
const WA = FMI.phone;           /* the couple's WhatsApp in a real invitation */
const TARGET = FMI.target;
const calm = FMI.reduceMotion || matchMedia("(prefers-reduced-motion: reduce)").matches;
const params = new URLSearchParams(FMI.search);
const preview = false;

/* guest name from ?to=Kumar-Family */
let guest = "";
try {
  guest = (params.get("to") || "").replace(/[-_+]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 40);
  guest = guest.split(" ").map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
} catch (e) {}
if (guest) {
  ["dear", "g-dear"].forEach(id => { $(id).textContent = "Dear " + guest + ","; $(id).hidden = false; });
  $("r-name").value = guest;
  document.title = "Dear " + guest + " · Rohan & Ishita's Engagement";
}

/* sounds, made in the browser */
let actx;
function ac(){ try { actx = actx || new (window.AudioContext || window.webkitAudioContext)(); if (actx.state === "suspended") actx.resume(); } catch (e) {} return actx; }
function chime(base, gain, when){
  const c = ac(); if (!c) return;
  try {
    const t0 = c.currentTime + .02 + (when || 0), out = c.createGain(); out.gain.value = gain || .06; out.connect(c.destination);
    [[1, 1, 2.2], [2, .35, 1.5], [3, .14, 1], [4.2, .06, .6]].forEach(([r, g, d]) => {
      const o = c.createOscillator(); o.type = "sine"; o.frequency.value = base * r;
      const v = c.createGain(); v.gain.setValueAtTime(0, t0); v.gain.linearRampToValueAtTime(g, t0 + .01); v.gain.exponentialRampToValueAtTime(.0001, t0 + d);
      o.connect(v); v.connect(out); o.start(t0); o.stop(t0 + d + .05);
    });
  } catch (e) {}
}
function shimmer(){ [1318.5, 1568, 1975.5, 2637].forEach((f, i) => chime(f, .025, i * .06)); }
function snap(){
  const c = ac(); if (!c) return;
  try {
    const n = Math.floor(c.sampleRate * .06), b = c.createBuffer(1, n, c.sampleRate), ch = b.getChannelData(0);
    for (let i = 0; i < n; i++) ch[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / n, 6);
    const s = c.createBufferSource(); s.buffer = b; const f = c.createBiquadFilter(); f.type = "lowpass"; f.frequency.value = 1400;
    const g = c.createGain(); g.gain.value = .8; s.connect(f); f.connect(g); g.connect(c.destination); s.start();
  } catch (e) {}
}

/* music: starts with the ring box, toggled from the corner button */
const music = $("music"), mBtn = $("music-btn");
let musicWanted = false;
function paintMusic(){ mBtn.classList.toggle("on", musicWanted); mBtn.setAttribute("aria-pressed", musicWanted); mBtn.setAttribute("aria-label", musicWanted ? "Pause music" : "Play music"); }
function setMusic(on){
  musicWanted = on;
  if (on) { music.volume = .75; const p = music.play(); if (p) p.catch(() => { musicWanted = false; paintMusic(); }); }
  else music.pause();
  paintMusic();
}
mBtn.addEventListener("click", () => setMusic(!musicWanted));
document.addEventListener("visibilitychange", () => { if (document.hidden) music.pause(); else if (musicWanted) music.play().catch(() => {}); });

/* gate: the box opens, light spills out */
const gate = $("gate");
let opened = false;
function openBox(){
  if (opened) return; opened = true;
  ac(); setMusic(true); mBtn.hidden = false;
  snap(); gate.classList.add("opened");
  setTimeout(() => [659.25, 830.6, 987.8, 1318.5].forEach((f, i) => chime(f, .05, i * .09)), 120);
  setTimeout(() => { document.body.classList.remove("locked"); gate.classList.add("gone"); update(); }, calm ? 300 : 1900);
  setTimeout(() => { gate.hidden = true; }, calm ? 1300 : 2950);
}
$("open").addEventListener("click", openBox);
$("g-box").addEventListener("click", openBox);
if (preview) { gate.hidden = true; document.body.classList.remove("locked"); }

/* the ring: drift slowly, spin when dragged, keep spinning with momentum */
const r3 = $("r3"), spin = $("spin");
let ringP = 0, ry = -18, vel = 0, drag = null, lastT = performance.now(), lastShimmer = 0;
const IDLE = calm ? 0 : 14;
function ringLoop(t){
  const dt = Math.min(.05, (t - lastT) / 1000); lastT = t;
  if (ringP > .2 && !drag) {
    /* settle face-on before the ring flies to her finger */
    const home = Math.round((ry + 18) / 360) * 360 - 18;
    vel = 0; ry += (home - ry) * Math.min(1, dt * 5);
  } else if (!drag) { vel += (IDLE - vel) * Math.min(1, dt * 1.6); ry += vel * dt; }
  r3.style.setProperty("--ry", ry.toFixed(1) + "deg");
  requestAnimationFrame(ringLoop);
}
requestAnimationFrame(ringLoop);
spin.addEventListener("pointerdown", e => {
  drag = { x: e.clientX, y: e.clientY, t: performance.now(), lock: null, id: e.pointerId };
});
addEventListener("pointermove", e => {
  if (!drag || e.pointerId !== drag.id) return;
  const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
  if (drag.lock === null && Math.abs(dx) + Math.abs(dy) > 6) drag.lock = Math.abs(dx) > Math.abs(dy) ? "x" : "y";
  if (drag.lock !== "x") return;
  const now = performance.now(), dt = Math.max(1, now - drag.t) / 1000;
  ry += dx * .9; vel = vel * .5 + (dx * .9 / dt) * .5;
  drag.x = e.clientX; drag.y = e.clientY; drag.t = now;
  if (Math.abs(vel) > 500 && now - lastShimmer > 700) { lastShimmer = now; shimmer(); }
}, { passive: true });
let suppressClick = false;
function endDrag(e){ if (drag && (!e || e.pointerId === drag.id)) { suppressClick = drag.lock === "x"; drag = null; } }
addEventListener("pointerup", endDrag); addEventListener("pointercancel", endDrag);
spin.addEventListener("click", () => { if (suppressClick) { suppressClick = false; return; } vel += 720; shimmer(); });

/* where the ring lands: the ring on Ishita's finger in the photo */
const ringbox = $("ringbox"), mark = $("mark");
function aimRing(){
  const rb = ringbox.getBoundingClientRect(), mk = mark.getBoundingClientRect(), st = ringbox.offsetParent.getBoundingClientRect();
  /* the floating ring's own centre before scroll moves it */
  const cx = st.left + ringbox.offsetLeft, cy = st.top + ringbox.offsetTop;
  ringbox.style.setProperty("--tx", (mk.left - cx).toFixed(1) + "px");
  const ts = parseFloat(getComputedStyle($("s-ring")).getPropertyValue("--ts")) || .62;
  ringbox.style.setProperty("--ty", (mk.top - cy + ringbox.offsetHeight * .266 * ts).toFixed(1) + "px");
}

/* scroll engine: each scene gets --p from 0 to 1 */
const scenes = [...document.querySelectorAll("[data-scene]")];
const root = document.documentElement, story = $("s-story"), dots = [...$("tl").children];
const ease = x => x * x * (3 - 2 * x);
let ticking = false;
function update(){
  const vh = innerHeight;
  for (const s of scenes) {
    const r = s.getBoundingClientRect();
    const pinned = s.classList.contains("scene");
    let p = pinned ? (calm ? 0 : -r.top / Math.max(1, r.height - vh)) : (vh - r.top) / (vh + r.height);
    p = Math.min(1, Math.max(0, p));
    s.style.setProperty("--p", p.toFixed(4));
    if (s.id === "s-ring") ringP = p;
    if (s === story && !calm) {
      const q = p < .12 ? 0 : p < .4 ? ease((p - .12) / .28) : p < .58 ? 1 : p < .86 ? 1 + ease((p - .58) / .28) : 2;
      s.style.setProperty("--q", q.toFixed(4));
      dots.forEach((d, i) => d.classList.toggle("on", Math.round(q) >= i));
    }
  }
  const max = root.scrollHeight - vh;
  root.style.setProperty("--gp", max > 0 ? (scrollY / max).toFixed(4) : 0);
  ticking = false;
}
addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(update); } }, { passive: true });
/* keep the names on one line: shrink if a long name would overflow */
function fitNames(){ const n = document.querySelector(".names"); n.style.fontSize = ""; let f = parseFloat(getComputedStyle(n).fontSize); while (n.scrollWidth > n.parentElement.clientWidth && f > 24) { f -= 2; n.style.fontSize = f + "px"; } }
addEventListener("resize", () => { aimRing(); fitNames(); update(); });
aimRing(); fitNames(); update();
if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => { fitNames(); aimRing(); });

/* reveal on view */
const io = "IntersectionObserver" in window ? new IntersectionObserver(es => es.forEach(e => {
  if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
}), { threshold: .15 }) : null;
document.querySelectorAll(".rv").forEach(el => io ? io.observe(el) : el.classList.add("in"));

/* sparkles around the wedding teaser */
(() => {
  const t = $("teaser");
  [[8, 18, 14, 2.6, 0], [88, 22, 18, 3, -1.2], [16, 76, 12, 2.2, -.6], [84, 72, 16, 2.8, -2], [50, 8, 10, 3.4, -1.6]].forEach(([x, y, s, d, dl]) => {
    const el = document.createElement("span"); el.className = "spk";
    el.style.cssText = "left:" + x + "%;top:" + y + "%;--s:" + s + "px;--d:" + d + "s;--dl:" + dl + "s;color:#FFE9C8";
    el.innerHTML = '<svg><use href="#star4"/></svg>'; t.appendChild(el);
  });
})();

/* countdown */
const cells = {}; document.querySelectorAll("#count b").forEach(b => cells[b.dataset.u] = b);
function tick(){
  let s = Math.floor((TARGET - Date.now()) / 1000);
  if (s <= 0) { $("count").innerHTML = '<p style="grid-column:1/-1;font-size:1.4rem;font-style:italic">Rohan and Ishita are engaged! Thank you for your love.</p>'; return; }
  const d = Math.floor(s / 86400); s -= d * 86400;
  const h = Math.floor(s / 3600); s -= h * 3600;
  const m = Math.floor(s / 60); s -= m * 60;
  cells.d.textContent = d;
  cells.h.textContent = String(h).padStart(2, "0");
  cells.m.textContent = String(m).padStart(2, "0");
  cells.s.textContent = String(s).padStart(2, "0");
  setTimeout(tick, 1000 - Date.now() % 1000);
}
tick();

/* calendar: Apple devices open the .ics, others get Google Calendar */
const CAL = FMI.calendar({ ring: { t: "Rohan & Ishita · Ring Ceremony", d: "20270307T133000Z/20270307T173000Z", l: "Taj West End, Race Course Road, Bengaluru" } });
if (!/iPhone|iPad|iPod|Macintosh/.test(navigator.userAgent)) document.querySelectorAll("[data-cal]").forEach(a => {
  const c = CAL[a.dataset.cal];
  a.href = "https://calendar.google.com/calendar/render?action=TEMPLATE&text=" + encodeURIComponent(c.t) + "&dates=" + c.d + "&location=" + encodeURIComponent(c.l) + "&details=" + encodeURIComponent("Invitation: https://findmyinvite.com/");
  a.target = "_blank"; a.rel = "noopener";
});

/* rsvp */
let guests = 2;
$("g-minus").addEventListener("click", () => { guests = Math.max(1, guests - 1); $("g-count").textContent = guests; });
$("g-plus").addEventListener("click", () => { guests = Math.min(15, guests + 1); $("g-count").textContent = guests; });
const form = $("rsvp-form");
form.addEventListener("change", () => {
  $("att-yes").style.display = form.querySelector("input[name=att]:checked").value === "yes" ? "grid" : "none";
});
form.addEventListener("submit", e => {
  e.preventDefault();
  const name = $("r-name").value.trim();
  if (!name) { $("r-err").hidden = false; $("r-name").focus(); return; }
  $("r-err").hidden = true;
  const yes = form.querySelector("input[name=att]:checked").value === "yes";
  const lines = ["RSVP · Rohan & Ishita's Ring Ceremony 💍", "", "Name: " + name, "Attending: " + (yes ? "Yes, wouldn't miss it" : "Sorry, can't make it")];
  if (yes) lines.push("Guests: " + guests);
  const w = $("r-msg").value.trim(); if (w) lines.push("Wishes: " + w);
  const url = "https://wa.me/" + WA + "?text=" + encodeURIComponent(lines.join("\n"));
  const win = FMI.open(url, "_blank"); if (!win) FMI.open(url);
});

/* share */
function toast(t){ const el = $("toast"); el.textContent = t; el.hidden = false; clearTimeout(toast.t); toast.t = setTimeout(() => el.hidden = true, 2200); }
$("share").addEventListener("click", async () => {
  const url = location.origin + FMI.instanceKey;
  try {
    if (navigator.share) { await FMI.share({ title: "Rohan & Ishita · Engagement Invitation", text: "You're invited to Rohan & Ishita's ring ceremony on 7 March 2027", url }); return; }
    await FMI.copyLink(url); toast("Invitation link copied");
  } catch (e) { if (e && e.name !== "AbortError") toast(url); }
});

FMI.ready();
})();
